commit 1a979ab4947fc259af01ea65263aaa4d417553fb
Author:     Philip Withnall <pwithnall@gnome.org>
AuthorDate: Tue Nov 14 11:00:21 2023 +0000
Commit:     Philip Withnall <pwithnall@gnome.org>
CommitDate: Tue Nov 14 11:00:21 2023 +0000

    gutils: Fix an unlikely minor leak in g_build_user_data_dir()

    A leak can happen if the `data_dir` is the empty string.

    See https://gitlab.gnome.org/GNOME/glib/-/jobs/3294034

    Signed-off-by: Philip Withnall <pwithnall@gnome.org>

diff --git a/glib/gutils.c b/glib/gutils.c
index dfe115843..ffc7d750c 100644
--- a/glib/gutils.c
+++ b/glib/gutils.c
@@ -1883,6 +1883,7 @@ g_build_user_data_dir (void)
   if (!data_dir || !data_dir[0])
     {
       gchar *home_dir = g_build_home_dir ();
+      g_free (data_dir);
       data_dir = g_build_filename (home_dir, ".local", "share", NULL);
       g_free (home_dir);
     }

