#!/usr/bin/env bash
# Focused differential leak harness for g_build_user_data_dir().
#
# Extracts the verbatim function text from the supplied source file and
# compiles it against mock GLib primitives whose allocations are tracked.
# G_OS_WIN32 is defined so the get_special_folder() branch (the only branch
# able to yield an allocated-but-empty data_dir) is exercised.  The mock
# get_special_folder() returns a freshly allocated empty string, which is the
# condition described by the upstream commit.
#
# Exit 0 => no leaked allocation remains after the function returns.
# Exit 1 => a leaked allocation remains (the vulnerable behaviour).
#
# Usage: leak_test.sh <path-to-gutils.c>
set -u

SRC="${1:-glib/gutils.c}"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BUILD="$(mktemp -d "$HERE/leak-build.XXXXXX")"
trap 'rm -rf "$BUILD"' EXIT

if [ ! -f "$SRC" ]; then
  echo "source not found: $SRC" >&2
  exit 2
fi

# Extract the exact function body from the supplied source.
awk '/^g_build_user_data_dir \(void\)$/{f=1} f{print} f&&/^}$/{exit}' "$SRC" > "$BUILD/func.inc"

if ! grep -q 'g_steal_pointer' "$BUILD/func.inc"; then
  echo "failed to extract g_build_user_data_dir() from $SRC" >&2
  exit 2
fi

cat > "$BUILD/harness.c" <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef char gchar;

static int live_allocs = 0;

static gchar *tracking_strdup (const gchar *s)
{
  size_t n;
  gchar *p;
  if (s == NULL)
    return NULL;
  n = strlen (s) + 1;
  p = (gchar *) malloc (n);
  if (p == NULL)
    return NULL;
  live_allocs++;
  memcpy (p, s, n);
  return p;
}

static void tracking_free (void *p)
{
  if (p != NULL)
    {
      live_allocs--;
      free (p);
    }
}

static gchar *g_strdup (const gchar *s) { return tracking_strdup (s); }
static void g_free (void *p) { tracking_free (p); }

static gchar *g_build_home_dir (void) { return tracking_strdup ("/home/user"); }

static gchar *g_build_filename (const gchar *first, ...)
{
  (void) first;
  return tracking_strdup ("/home/user/.local/share");
}

/* When NULL, the platform (get_special_folder) branch is exercised; when set
 * to a non-empty string, the XDG_DATA_HOME branch is exercised. */
static const gchar *mock_xdg = NULL;

static const gchar *g_getenv (const gchar *name)
{
  (void) name;
  return mock_xdg;
}

/* Mock for the G_OS_WIN32 branch.  Returns an allocated empty string. */
#ifdef G_OS_WIN32
static gchar *get_special_folder (void *folderid)
{
  (void) folderid;
  return tracking_strdup ("");
}

static int FOLDERID_LocalAppData = 0;
#endif

static void *g_steal_pointer_impl (void **pp)
{
  void *v = *pp;
  *pp = NULL;
  return v;
}
#define g_steal_pointer(pp) g_steal_pointer_impl ((void **) (pp))

/* The verbatim target implementation, extracted from the supplied source. */
static gchar *
#include "func.inc"

int
main (int argc, char **argv)
{
  gchar *result;

  if (argc > 1)
    mock_xdg = argv[1];

  result = g_build_user_data_dir ();
  printf ("branch=%s result=%s\n", mock_xdg ? "XDG_DATA_HOME" : "fallback",
          result ? result : "(null)");
  g_free (result);
  printf ("live_allocs=%d\n", live_allocs);
  if (live_allocs != 0)
    {
      printf ("LEAK: %d allocation(s) leaked\n", live_allocs);
      return 1;
    }
  printf ("OK: no leak\n");
  return 0;
}
EOF

if [ "${LEAK_TEST_NOWIN32:-0}" = "1" ]; then
